<script setup>
import { computed,ref } from 'vue'
import { data as records } from '../pets.data'
const board=ref(''),slot=ref(''),mode=ref(''),role=ref(''),characterClass=ref('')
const classes=computed(()=>[...new Set(records.flatMap(r=>r.classIds))])
const filtered=computed(()=>records.filter(r=>(!board.value||r.board===board.value)&&(!slot.value||r.slot===Number(slot.value))&&(!mode.value||r.mode===mode.value)&&(!role.value||r.role===role.value)&&(!characterClass.value||!r.classIds.length||r.classIds.includes(characterClass.value))))
const value=(v,unit)=>v===null?'Unbekannt':new Intl.NumberFormat('de-DE').format(v)+(unit==='percent'?' %':'')
</script>
<template><section aria-labelledby="pet-values-title" class="pet-values"><h2 id="pet-values-title">Geprüfte Analysewerte</h2><p v-if="!records.length">Es sind noch keine geprüften Werte zur Veröffentlichung freigegeben.</p><template v-else><div class="pet-value-filters"><label>Brett<select v-model="board"><option value="">Alle</option><option v-for="b in ['Cognia','Fera','Natura','Varia','Specia']">{{b}}</option></select></label><label>Slot<select v-model="slot"><option value="">Alle</option><option v-for="i in 9" :value="i">{{i}}</option></select></label><label>Modus<select v-model="mode"><option value="">Alle</option><option value="pve">PvE</option><option value="pvp">PvP</option></select></label><label>Rolle<select v-model="role"><option value="">Alle</option><option value="dps">Schaden</option><option value="tank">Tank</option><option value="healer">Heiler</option><option value="support">Support</option></select></label><label>Klasse<select v-model="characterClass"><option value="">Alle</option><option v-for="c in classes">{{c}}</option></select></label></div><p aria-live="polite">{{filtered.length}} passende Werte</p><div class="pet-table"><table><thead><tr><th>Brett / Slot</th><th>Effekt</th><th>Minimum</th><th>Maximum</th><th>Academy-Empfehlung</th><th>Geltungsbereich</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td>{{r.board}} / {{r.slot}}</td><td>{{r.effect}}</td><td>{{value(r.min,r.unit)}}</td><td>{{value(r.max,r.unit)}}</td><td>{{r.recommendation?value(r.recommendation.value,r.unit):'Keine Stoppschwelle'}}<small v-if="r.recommendation">{{r.recommendation.rationale}}</small></td><td>{{r.verification.region}} · {{r.verification.patch}}<small>{{r.mode.toUpperCase()}} · {{r.role}}</small></td></tr></tbody></table></div><p>Stoppschwellen sind Empfehlungen der Academy und keine offiziellen Spielgrenzen.</p></template></section></template>
<style scoped>.pet-value-filters{display:flex;flex-wrap:wrap;gap:16px;margin:24px 0}.pet-value-filters label{display:grid;gap:6px;font-size:15px;color:#bdc9d7}.pet-value-filters select{background:#17212e;border:1px solid #536174;border-radius:4px;padding:8px 12px;color:#eeeae2;min-height:42px;color-scheme:dark}.pet-table{overflow:auto}.pet-table table{display:table;white-space:normal}.pet-table small{display:block;color:#b4bdc9;margin-top:6px;min-width:130px}.pet-values select:focus-visible{outline:2px solid #d7b777;outline-offset:3px}</style>
